using System.Collections.Generic; using UnityEditor;
namespace UnityCli { public class BuildSettingsSetTool : IUnityCliTool<BuildSettingsSetTool.Request, BuildSettingsResult> { public sealed class Request { public string ProductName { get; set; } public string BundleVersion { get; set; } public string CompanyId { get; set; } public string ApplicationIdentifier { get; set; } public string ScriptingBackend { get; set; } public string ApiCompatibilityLevel { get; set; } } public ToolDescriptor Describe() => new() { Name = "build.settings.set", Summary = "Update persistent Unity PlayerSettings build configuration, with dry-run support.", Description = "Updates provided PlayerSettings fields: productName, bundleVersion, companyId, applicationIdentifier, scriptingBackend, and apiCompatibilityLevel. Requires --yes because it writes ProjectSettings. dryRun=true previews without writing. Available in Edit and Play mode.", Group = "build", Version = "1.0.0", DestructiveHint = true, SupportsDryRun = true, SideEffects = new[] { "player-settings-write" }, Target = "editor", PlayModeSupport = "editor-only", DefaultTimeoutMs = 30000, MaxTimeoutMs = 600000, Examples = new[] { new ToolExample { Description = "Set product name", Input = new Request { ProductName = "My Game" }, Execution = new ToolExampleExecution { DryRun = true } } } }; public System.Threading.Tasks.ValueTask<BuildSettingsResult> ExecuteAsync(Request request, UnityCliProjectToolContext ctx, System.Threading.CancellationToken ct = default) { if (ctx.DryRun) return new(new BuildSettingsResult { ProductName = request.ProductName, BundleVersion = request.BundleVersion, CompanyId = request.CompanyId, ApplicationIdentifier = request.ApplicationIdentifier, ScriptingBackend = request.ScriptingBackend, ApiCompatibilityLevel = request.ApiCompatibilityLevel, DryRun = true }); var changed = new List<string>(); if (!string.IsNullOrEmpty(request.ProductName)) { PlayerSettings.productName = request.ProductName; changed.Add("productName"); } if (!string.IsNullOrEmpty(request.BundleVersion)) { PlayerSettings.bundleVersion = request.BundleVersion; changed.Add("bundleVersion"); } if (!string.IsNullOrEmpty(request.CompanyId)) { PlayerSettings.companyName = request.CompanyId; changed.Add("companyId"); } if (!string.IsNullOrEmpty(request.ApplicationIdentifier)) { PlayerSettings.SetApplicationIdentifier(BuildTargetGroup.Unknown, request.ApplicationIdentifier); changed.Add("applicationIdentifier"); } if (!string.IsNullOrEmpty(request.ScriptingBackend) && System.Enum.TryParse(request.ScriptingBackend, true, out ScriptingImplementation backend)) { PlayerSettings.SetScriptingBackend(BuildTargetGroup.Unknown, backend); changed.Add("scriptingBackend"); } if (!string.IsNullOrEmpty(request.ApiCompatibilityLevel) && System.Enum.TryParse(request.ApiCompatibilityLevel, true, out ApiCompatibilityLevel level)) { PlayerSettings.SetApiCompatibilityLevel(BuildTargetGroup.Unknown, level); changed.Add("apiCompatibilityLevel"); } var result = BuildSettingsToolSupport.Read(); result.Changed = changed; return new(result); } } }
